-- Isolated campaign domain. All seeded content is draft; schedules are disabled.
create table if not exists community_campaign(id uuid primary key default gen_random_uuid(),campaign_key text not null unique,name text not null,status text not null default 'paused' check(status in ('paused','active','archived')),timezone text not null default 'Africa/Addis_Ababa',rotation_position integer not null default 1 check(rotation_position between 1 and 30),starts_at timestamptz,ends_at timestamptz,created_by uuid references app_user(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists community_campaign_message_version(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references community_campaign(id) on delete cascade,message_number integer not null check(message_number between 1 and 30),version integer not null check(version>0),internal_title text not null,notification_title text not null,body text not null,quran_text text not null,hadith_text text not null,action_label text not null,action_url text not null,audience text not null check(audience in ('all_opted_in','members_and_public','professionals')),status text not null default 'draft' check(status in ('draft','submitted_for_review','approved','rejected','archived')),authored_by uuid references app_user(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(campaign_id,message_number,version));
create index if not exists ix_community_campaign_versions on community_campaign_message_version(campaign_id,message_number,version desc);
create table if not exists community_campaign_approval(id uuid primary key default gen_random_uuid(),message_version_id uuid not null references community_campaign_message_version(id) on delete restrict,author_user_id uuid references app_user(id) on delete set null,approver_user_id uuid not null references app_user(id) on delete restrict,decision text not null check(decision in ('approved','rejected')),review_note text,approved_content_sha256 text not null,created_at timestamptz not null default now(),check(author_user_id is null or author_user_id<>approver_user_id));
create unique index if not exists uq_community_campaign_approval on community_campaign_approval(message_version_id);
create table if not exists community_campaign_schedule(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references community_campaign(id) on delete cascade,slot_key text not null unique check(slot_key in ('friday_afternoon','sunday_morning')),day_of_week integer not null check(day_of_week between 0 and 6),local_time time not null,timezone text not null default 'Africa/Addis_Ababa',enabled boolean not null default false,paused_at timestamptz,selected_message_version_id uuid references community_campaign_message_version(id) on delete restrict,next_run_at timestamptz,last_run_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists community_campaign_delivery(id uuid primary key default gen_random_uuid(),schedule_id uuid not null references community_campaign_schedule(id) on delete restrict,message_version_id uuid not null references community_campaign_message_version(id) on delete restrict,slot_occurrence timestamptz not null,recipient_type text not null check(recipient_type in ('member','public_subscriber')),recipient_id uuid not null,notification_event_id uuid references notification_event(id) on delete set null,status text not null default 'pending' check(status in ('pending','sent','failed','skipped')),reason_code text,attempts integer not null default 0,delivered_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(schedule_id,message_version_id,slot_occurrence,recipient_type,recipient_id));
create index if not exists ix_community_campaign_delivery_monitor on community_campaign_delivery(schedule_id,slot_occurrence,status);
create table if not exists community_campaign_push_delivery(id uuid primary key default gen_random_uuid(),delivery_id uuid not null references community_campaign_delivery(id) on delete cascade,subscription_id uuid not null references notification_push_subscription(id) on delete restrict,endpoint_sha256 text not null,status text not null default 'pending' check(status in ('pending','sending','sent','failed','skipped')),attempts integer not null default 0,available_at timestamptz not null default now(),last_error_code text,last_status_code integer,delivered_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(delivery_id,subscription_id));
create table if not exists community_campaign_public_subscriber(id uuid primary key default gen_random_uuid(),email text,consent_token_sha256 text not null unique,consented_at timestamptz not null,revoked_at timestamptz,push_endpoint text,endpoint_sha256 text,p256dh text,auth_secret text,permission_granted boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(email is not null or push_endpoint is not null));
create unique index if not exists uq_community_campaign_public_endpoint on community_campaign_public_subscriber(endpoint_sha256) where endpoint_sha256 is not null and revoked_at is null;
create table if not exists community_campaign_audit_event(id uuid primary key default gen_random_uuid(),actor_user_id uuid references app_user(id) on delete set null,action text not null,resource_type text not null,resource_id uuid,request_id text,outcome text not null,reason_code text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table notification_preference add column if not exists community_campaign_enabled boolean not null default false;
insert into community_campaign(campaign_key,name,status,timezone) values('community-contribution','Community Contribution Campaign','paused','Africa/Addis_Ababa') on conflict(campaign_key) do nothing;
insert into community_campaign_message_version(campaign_id,message_number,version,internal_title,notification_title,body,quran_text,hadith_text,action_label,action_url,audience,status)
select c.id,v.message_number,1,v.internal_title,v.notification_title,v.body,v.quran_text,v.hadith_text,v.action_label,v.action_url,v.audience,'draft' from community_campaign c cross join (values
(gen_random_uuid(),'A small act can open a door',1,1,'One useful act this week','A stronger community is built through practical acts, not good intentions alone. Could you give one hour, share one useful skill, or help solve one local problem this week? Start with an action that matches your time and ability.','“Cooperate in righteousness and piety.” — Qur''an 5:2','“Allah helps the servant as long as the servant helps their brother.” — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Explore community initiatives','/serve-community','all_opted_in'),
(gen_random_uuid(),'Share what you have learned',2,1,'Your knowledge can travel further','A lesson learned through years of study or work may save someone else months of uncertainty. Share a practical lesson, host a short knowledge session, or contribute a resource that others can use.','“My Lord, increase me in knowledge.” — Qur''an 20:114','The Prophet ﷺ praised those who learn the Qur''an and teach it. — Sahih al-Bukhari 5027. [Source](https://sunnah.com/bukhari:5027)','Join knowledge-sharing and mentoring','/mentorship','members_and_public'),
(gen_random_uuid(),'Mentor one emerging professional',3,1,'Be the guidance you once needed','A thoughtful conversation can help a student or early-career professional see a path forward. Offer a mentoring conversation, review a CV, or help someone prepare for a professional challenge.','“And speak to people good words.” — Qur''an 2:83','The Prophet ﷺ taught that seeking a path of knowledge is a path made easier toward Paradise. — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Explore mentoring opportunities','/mentorship','members_and_public'),
(gen_random_uuid(),'Offer a professional hour',4,1,'Could you give one hour?','Your professional experience may help a community group make a safer, clearer or more sustainable decision. Consider offering one pro bono consultation in your area of expertise, with a clear scope and realistic time commitment.','“Do good; indeed, Allah loves the doers of good.” — Qur''an 2:195','“The upper hand is better than the lower hand.” — Sahih al-Bukhari 1427. [Source](https://sunnah.com/bukhari:1427)','Offer a community service','/serve-community','professionals'),
(gen_random_uuid(),'Build something together',5,1,'Bring one idea to the table','Is there a challenge in your neighbourhood, profession or community that people could address together? Share a specific idea, the people it could help, and one achievable first step. Collaboration turns ideas into service.','“Consult them in the matter.” — Qur''an 3:159','A believer supports another believer like parts of a building supporting one another. — Sahih Muslim 2585. [Source](https://sunnah.com/muslim:2585)','Propose or join an initiative','/serve-community','all_opted_in'),
(gen_random_uuid(),'Help make a difficult task easier',6,1,'Make the next step easier','Someone may be navigating an unfamiliar process, a job search, a study decision or a community service. Offer a clear explanation, a useful introduction or a practical checklist. Small help can remove a real barrier.','“Allah intends for you ease and does not intend hardship for you.” — Qur''an 2:185','“Make things easy and do not make them difficult.” — Sahih al-Bukhari 6125. [Source](https://sunnah.com/bukhari:6125)','Find a way to contribute','/serve-community','all_opted_in'),
(gen_random_uuid(),'Look after the people nearby',7,1,'Notice who may need support','Community care begins close to home. Check whether a neighbour, student, older person or local group needs a practical hand. Listen first, respect dignity and offer help without making someone’s circumstances public.','Qur''an 4:36 calls for kindness to parents, relatives, orphans, people in need and neighbours.','Gabriel repeatedly advised the Prophet ﷺ to treat neighbours kindly. — Sahih al-Bukhari 6014. [Source](https://sunnah.com/bukhari:6014)','Explore local community service','/serve-community','all_opted_in'),
(gen_random_uuid(),'Give useful feedback',8,1,'Help an idea become workable','If a community initiative is being planned, thoughtful feedback can make it more useful and realistic. Share a constructive suggestion, identify a risk respectfully, or help the team measure whether the initiative is helping.','“Help one another in righteousness and piety.” — Qur''an 5:2','“Speak what is good or remain silent.” — Sahih al-Bukhari 6018. [Source](https://sunnah.com/bukhari:6018)','Explore current initiatives','/serve-community','members_and_public'),
(gen_random_uuid(),'Teach one practical skill',9,1,'Pass on one practical skill','Could you teach a useful skill in a short session—digital literacy, financial basics, communication, research, safety, or a professional tool? Keep it practical, welcoming and accessible to beginners.','“Are those who know equal to those who do not know?” — Qur''an 39:9','The Prophet ﷺ praised learning and teaching beneficial knowledge. — Sahih al-Bukhari 5027. [Source](https://sunnah.com/bukhari:5027)','Share knowledge or mentor','/mentorship','members_and_public'),
(gen_random_uuid(),'Make room for a new voice',10,1,'Invite someone into the conversation','Strong communities make room for emerging voices. Invite a student, graduate, young professional or community volunteer to contribute an idea, ask a question or take part in a learning session.','“And consult them in the matter.” — Qur''an 3:159','The believers support one another like a building whose parts strengthen each other. — Sahih Muslim 2585. [Source](https://sunnah.com/muslim:2585)','Explore mentoring and participation','/mentorship','members_and_public'),
(gen_random_uuid(),'Support a job seeker',11,1,'Help someone move toward work','A useful referral, a CV review or a realistic interview practice session may help someone take their next step. Share opportunities responsibly and never promise an outcome you cannot control.','“And do good; indeed, Allah loves the doers of good.” — Qur''an 2:195','Allah helps a servant who helps another. — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Explore opportunities and professional support','/jobs','members_and_public'),
(gen_random_uuid(),'Volunteer with care',12,1,'Choose a commitment you can keep','Sustainable volunteering starts with an honest commitment. Choose a task that fits your time, skills and capacity, agree on expectations, and communicate early if your availability changes. Reliability is itself a service.','“Allah does not burden a soul beyond its capacity.” — Qur''an 2:286','“Make things easy and do not make them difficult.” — Sahih al-Bukhari 6125. [Source](https://sunnah.com/bukhari:6125)','Find a suitable volunteer activity','/serve-community','all_opted_in'),
(gen_random_uuid(),'Contribute to a shared solution',13,1,'Your perspective matters','Community challenges often need different perspectives: technical, educational, legal, health, business, creative and lived experience. Offer your perspective respectfully and help the group move from discussion to a practical next step.','“And their affairs are conducted by consultation among them.” — Qur''an 42:38','A believer strengthens another believer, like the parts of a building. — Sahih Muslim 2585. [Source](https://sunnah.com/muslim:2585)','Join or propose an initiative','/serve-community','all_opted_in'),
(gen_random_uuid(),'Make service accessible',14,1,'A welcoming first step matters','Help make community participation easier for people with different schedules, experience and abilities. Explain the task clearly, welcome questions, and avoid creating unnecessary barriers for someone who wants to help.','“Allah intends for you ease.” — Qur''an 2:185','“Allah is Gentle and loves gentleness.” — Sunan Ibn Majah 3688 (graded Sahih by Darussalam on Sunnah.com). [Source](https://sunnah.com/ibnmajah:3688)','Explore ways to participate','/serve-community','all_opted_in'),
(gen_random_uuid(),'Begin with one good word',15,1,'Encourage someone today','A respectful message of encouragement, a useful introduction or a sincere thank-you can strengthen someone’s confidence. Reach out to a person contributing quietly and let them know their effort is valued.','“Speak to people good words.” — Qur''an 2:83','The Prophet ﷺ taught: “Speak what is good or remain silent.” — Sahih al-Bukhari 6018. [Source](https://sunnah.com/bukhari:6018)','Connect through the community','/members','all_opted_in'),
(gen_random_uuid(),'Remove one obstacle',16,1,'What can you make easier?','Look for one obstacle that prevents people from learning, working or accessing a service. Could you explain a process, improve a resource, make an introduction or help remove a practical barrier?','“Whoever saves one life, it is as if they saved all mankind.” — Qur''an 5:32 (reflect on the value of protecting life; do not use this verse to overstate the scale of a routine service).','The Prophet ﷺ encouraged removing harmful things from the road. — Sunan Ibn Majah 3681 (graded Sahih by Darussalam on Sunnah.com). [Source](https://sunnah.com/ibnmajah:3681)','Find a practical service opportunity','/serve-community','all_opted_in'),
(gen_random_uuid(),'Share a resource',17,1,'A useful resource can help many','Do you know a reliable guide, learning resource, public service or professional tool that could help others? Share it with a short explanation of who it is useful for and any limitations people should know.','“Cooperate in righteousness and piety.” — Qur''an 5:2','The Prophet ﷺ praised beneficial knowledge that continues to benefit people. — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Share knowledge with the community','/mentorship','members_and_public'),
(gen_random_uuid(),'Be a bridge between people',18,1,'Connect people to possibilities','You may know someone with a skill and another person who needs it. With permission, make a thoughtful introduction between a learner, mentor, volunteer or initiative team. Protect privacy and let both people choose whether to connect.','“And cooperate in righteousness and piety.” — Qur''an 5:2','Allah helps the servant who helps their brother. — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Explore the MPA community network','/members','members_and_public'),
(gen_random_uuid(),'Offer a pro bono review',19,1,'Put your expertise to community use','A community organisation may need a short review of a budget, design, policy, website, legal process or project plan. If you are qualified, offer a clearly scoped pro bono review and state what is outside your expertise.','“Allah commands justice and good conduct.” — Qur''an 16:90','Establishing justice between people is described as charity. — Sahih al-Bukhari 2707. [Source](https://sunnah.com/bukhari:2707)','Offer professional service','/serve-community','professionals'),
(gen_random_uuid(),'Make collaboration stronger',20,1,'Strengthen the team around you','A good team shares responsibility, communicates clearly and respects each contributor. If you are part of an initiative, ask what support is needed, agree on a small task and help the team complete it.','“And hold firmly together to the rope of Allah and do not become divided.” — Qur''an 3:103','“A believer is like a building, each part strengthening the other.” — Sahih Muslim 2585. [Source](https://sunnah.com/muslim:2585)','Join a community initiative','/serve-community','all_opted_in'),
(gen_random_uuid(),'Help someone learn with confidence',21,1,'Make learning feel possible','Encourage a learner by listening to their goal, helping them identify the next step and sharing feedback with kindness. Mentoring is not about having every answer; it is about helping someone learn to find answers.','“Say: My Lord, increase me in knowledge.” — Qur''an 20:114','The Prophet ﷺ praised those who learn and teach. — Sahih al-Bukhari 5027. [Source](https://sunnah.com/bukhari:5027)','Become a mentor or find one','/mentorship','members_and_public'),
(gen_random_uuid(),'Give without diminishing dignity',22,1,'Let help preserve dignity','When offering support, ask what is useful, protect privacy and respect the recipient’s choices. Effective community service helps people retain agency; it does not turn their needs into public stories or publicity.','Qur''an 2:263 teaches that kind words and forgiveness are better than charity followed by hurt.','The Prophet ﷺ taught that Allah helps the servant who helps another. — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Explore respectful community service','/serve-community','all_opted_in'),
(gen_random_uuid(),'Support your neighbours',23,1,'Community begins nearby','Think of one practical way to support people around you: share a useful contact, help someone access a service, offer a learning opportunity or contribute to a local initiative. Keep the offer sincere and respectful.','Qur''an 4:36 calls for kindness to neighbours and people in need.','The Prophet ﷺ said that Gabriel continued advising him about neighbours. — Sahih al-Bukhari 6014. [Source](https://sunnah.com/bukhari:6014)','Find a community contribution','/serve-community','all_opted_in'),
(gen_random_uuid(),'Make your experience useful',24,1,'Your experience can guide a next step','What do you know now that you wish you had known earlier? Turn that lesson into a short guide, discussion or mentoring session. Practical experience becomes more valuable when it is shared responsibly.','“Are those who know equal to those who do not know?” — Qur''an 39:9','The Prophet ﷺ described ongoing charity and beneficial knowledge among deeds whose benefit continues after death. — Sahih Muslim 1631. [Source](https://sunnah.com/muslim:1631)','Share your knowledge','/mentorship','professionals'),
(gen_random_uuid(),'Choose fairness in your work',25,1,'Let fairness shape your contribution','Whether you are reviewing a proposal, recommending a candidate or allocating volunteer work, act fairly and explain decisions clearly. Trust grows when people are treated with consistency and respect.','“Stand firm for justice, as witnesses for Allah.” — Qur''an 4:135','“Establishing justice between people is charity.” — Sahih al-Bukhari 2707. [Source](https://sunnah.com/bukhari:2707)','Contribute to a fairer community','/serve-community','all_opted_in'),
(gen_random_uuid(),'Welcome a first-time volunteer',26,1,'Help someone take their first step','Remember how it feels to join something new. Explain the purpose, introduce the team, describe the task and make space for questions. A welcoming first experience can help someone contribute with confidence.','“And speak to people good words.” — Qur''an 2:83','“Make things easy and do not make them difficult.” — Sahih al-Bukhari 6125. [Source](https://sunnah.com/bukhari:6125)','Join or support a volunteer activity','/serve-community','all_opted_in'),
(gen_random_uuid(),'Share an opportunity responsibly',27,1,'Pass along a genuine opportunity','If you share a job, scholarship, training or volunteering opportunity, check that the information is current and the source is trustworthy. Include eligibility and deadlines, and never promise selection or employment.','“And cooperate in righteousness and piety.” — Qur''an 5:2','Allah helps a servant who helps another. — Sahih Muslim 2699. [Source](https://sunnah.com/muslim:2699)','Explore and share opportunities','/jobs','members_and_public'),
(gen_random_uuid(),'Turn reflection into action',28,1,'One intention, one practical step','Choose one community need you care about and write down a small action you can complete this week. Invite one other person if collaboration would help. Keep the commitment realistic, measurable and respectful.','“And say, ‘Do [as you will], for Allah will see your deeds…’” — Qur''an 9:105 (short excerpt; retain the verse context in the full reference).','The Prophet ﷺ taught that every day offers an opportunity for charity through good action. — Sahih al-Bukhari 2707. [Source](https://sunnah.com/bukhari:2707)','Take a first step in community service','/serve-community','all_opted_in'),
(gen_random_uuid(),'Keep kindness gentle',29,1,'Make your help gentle and respectful','The way we help matters. Listen without judgement, offer options rather than pressure, and respect a person''s decision. Kindness and gentleness help make community participation safer and more welcoming.','“So by mercy from Allah, you were gentle with them.” — Qur''an 3:159','“Allah is Gentle and loves gentleness.” — Sunan Ibn Majah 3688 (graded Sahih by Darussalam on Sunnah.com). [Source](https://sunnah.com/ibnmajah:3688)','Explore a way to serve','/serve-community','all_opted_in'),
(gen_random_uuid(),'Continue the good together',30,1,'Keep the good moving forward','Thank you to everyone who has shared knowledge, mentored, volunteered, offered a professional service or supported an initiative. What is one contribution you can continue, improve or invite someone else to join?','“Whoever does an atom’s weight of good will see it.” — Qur''an 99:7','The Prophet ﷺ described ongoing charity and beneficial knowledge among deeds whose benefit continues after death. — Sahih Muslim 1631. [Source](https://sunnah.com/muslim:1631)','Continue contributing to the community','/serve-community','all_opted_in')
) as v(id_placeholder,internal_title,message_number,version,notification_title,body,quran_text,hadith_text,action_label,action_url,audience) where c.campaign_key='community-contribution' on conflict(campaign_id,message_number,version) do nothing;
insert into community_campaign_schedule(campaign_id,slot_key,day_of_week,local_time,timezone,enabled) select id,'friday_afternoon',5,'15:00'::time,'Africa/Addis_Ababa',false from community_campaign where campaign_key='community-contribution' on conflict(slot_key) do nothing;
insert into community_campaign_schedule(campaign_id,slot_key,day_of_week,local_time,timezone,enabled) select id,'sunday_morning',0,'09:00'::time,'Africa/Addis_Ababa',false from community_campaign where campaign_key='community-contribution' on conflict(slot_key) do nothing;
